from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, capacity_bytes)
        self.probation = OrderedDict()
        self.protected = OrderedDict()
        self.ghost_probation = OrderedDict()
        self.ghost_protected = OrderedDict()
        self.ghost_limit = 4096
        self.protected_target = self.capacity_bytes // 2
        self.used_bytes = 0
        self.sketch_mask = 4095
        self.sketch = [0] * (self.sketch_mask + 1)
        self.sample_count = 0
        self.mask64 = (1 << 64) - 1

    def _slot(self, key, salt):
        x = (key ^ salt) & self.mask64
        x = ((x ^ (x >> 30)) * 0xbf58476d1ce4e5b9) & self.mask64
        x = ((x ^ (x >> 27)) * 0x94d049bb133111eb) & self.mask64
        x ^= x >> 31
        return x & self.sketch_mask

    def _record(self, key):
        for salt in (0x243f6a8885a308d3, 0x13198a2e03707344, 0xa4093822299f31d0, 0x082efa98ec4e6c89):
            index = self._slot(key, salt)
            if self.sketch[index] < 15:
                self.sketch[index] += 1
        self.sample_count += 1
        if self.sample_count >= 2048:
            self.sample_count = 0
            self.sketch = [(value + 1) // 2 for value in self.sketch]

    def _estimate(self, key):
        return min(
            self.sketch[self._slot(key, 0x243f6a8885a308d3)],
            self.sketch[self._slot(key, 0x13198a2e03707344)],
            self.sketch[self._slot(key, 0xa4093822299f31d0)],
            self.sketch[self._slot(key, 0x082efa98ec4e6c89)],
        )

    def _remember(self, ghost, key):
        ghost.pop(key, None)
        ghost[key] = None
        while len(ghost) > self.ghost_limit:
            ghost.popitem(last=False)

    def _forget_ghost(self, key):
        self.ghost_probation.pop(key, None)
        self.ghost_protected.pop(key, None)

    def _rebalance(self):
        protected_bytes = sum(self.protected.values())
        while self.protected and protected_bytes > self.protected_target:
            old_key, old_size = self.protected.popitem(last=False)
            self.probation[old_key] = old_size
            protected_bytes -= old_size

    def _peek_victim(self):
        if self.probation:
            return next(iter(self.probation.items()))
        if self.protected:
            return next(iter(self.protected.items()))
        return None

    def _evict_one(self):
        if self.probation:
            old_key, old_size = self.probation.popitem(last=False)
            self._remember(self.ghost_probation, old_key)
        elif self.protected:
            old_key, old_size = self.protected.popitem(last=False)
            self._remember(self.ghost_protected, old_key)
        else:
            return None
        self.used_bytes -= old_size
        return old_key

    def access(self, key: int, size: int, now: int) -> list[int]:
        if key in self.protected:
            stored_size = self.protected.pop(key)
            self.protected[key] = stored_size
            self._record(key)
            return []

        if key in self.probation:
            stored_size = self.probation.pop(key)
            self.protected[key] = stored_size
            self._record(key)
            self._rebalance()
            return []

        if size <= 0 or size > self.capacity_bytes or self.capacity_bytes == 0:
            return []

        self._record(key)
        step = max(1, self.capacity_bytes // 16)
        if key in self.ghost_probation:
            self.protected_target = min(
                self.capacity_bytes,
                self.protected_target + max(step, min(size, self.capacity_bytes)),
            )
        elif key in self.ghost_protected:
            self.protected_target = max(
                0,
                self.protected_target - max(step, min(size, self.capacity_bytes)),
            )
        self._forget_ghost(key)

        if self.used_bytes + size > self.capacity_bytes:
            victim = self._peek_victim()
            if victim is None or self._estimate(key) < self._estimate(victim[0]):
                return []

        evicted = []
        while self.used_bytes + size > self.capacity_bytes:
            old_key = self._evict_one()
            if old_key is None:
                return evicted
            evicted.append(old_key)

        self.probation[key] = size
        self.used_bytes += size
        self._rebalance()
        return evicted
